using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (source-gen context)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for Person: {personInfo.Type.Name}");
Console.WriteLine($"  Serialize check: {JsonSerializer.Serialize(new Person("Alice", 30), personInfo)}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
bool found = options.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo for Order (not in resolver): found={found}, info={orderInfo?.Type.Name ?? "(null)"}");

// Also confirm the positive case
bool foundPerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? personInfo2);
Console.WriteLine($"TryGetTypeInfo for Person (in resolver):    found={foundPerson}, info={personInfo2?.Type.Name ?? "(null)"}");

// Types
public record Person(string Name, int Age);
public record Order(int Id, decimal Total); // intentionally NOT in the source-gen context

[JsonSerializable(typeof(Person))]
public partial class MyContext : JsonSerializerContext;

